{
  "items": [
    {
      "name": "Polynomial.hasseDeriv",
      "module_name": "Mathlib.Algebra.Polynomial.HasseDeriv",
      "kind": "definition",
      "type": "{R : Type u_1} → [inst : Semiring R] → ℕ → Polynomial R →ₗ[R] Polynomial R"
    },
    {
      "name": "Polynomial.iterate_derivative_eq_factorial_smul_sum",
      "module_name": "Mathlib.Algebra.Polynomial.Derivative",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] (p : Polynomial R) (k : ℕ),\n  (⇑Polynomial.derivative)^[k] p =\n    k.factorial •\n      ∑ x ∈ ((⇑Polynomial.derivative)^[k] p).support,\n        Polynomial.C ((x + k).choose k • p.coeff (x + k)) * Polynomial.X ^ x"
    },
    {
      "name": "Polynomial.iterate_derivative_prod_X_sub_C",
      "module_name": "Mathlib.Algebra.Polynomial.Derivative",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : CommRing R] {k : ℕ} {S : Finset R},\n  k ≤ S.card →\n    (⇑Polynomial.derivative)^[k] (∏ a ∈ S, (Polynomial.X - Polynomial.C a)) =\n      ↑k.factorial * ∑ T ∈ Finset.powersetCard (S.card - k) S, ∏ a ∈ T, (Polynomial.X - Polynomial.C a)"
    },
    {
      "name": "Polynomial.natDegree_hasseDeriv_le",
      "module_name": "Mathlib.Algebra.Polynomial.HasseDeriv",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] (p : Polynomial R) (n : ℕ),\n  ((Polynomial.hasseDeriv n) p).natDegree ≤ p.natDegree - n"
    },
    {
      "name": "Polynomial.factorial_smul_hasseDeriv",
      "module_name": "Mathlib.Algebra.Polynomial.HasseDeriv",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] (k : ℕ), ⇑(k.factorial • Polynomial.hasseDeriv k) = (⇑Polynomial.derivative)^[k]"
    }
  ]
}
